from h import *
R(9956832,"رقائق خبز البيتا في القلّاية الهوائية",
"رقائق خبز البيتا في القلّاية الهوائية وجبة خفيفة بسيطة ولذيذة جاهزة في أقل من 10 دقائق!",
"حصتان","حصة واحدة",
["2 رغيف خبز بيتا من القمح الكامل أو ما تختاره","1 ملعقة كبيرة أكوافابا (ماء الحمص) أو زيت من اختيارك إن فضّلت","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة بقدونس مجفف","¼ ملعقة صغيرة ملح البحر"],
["قطّع خبز البيتا إلى 8 قطع مثلثة. واستخدام قاطعة البيتزا طريقة سريعة للقيام بذلك. ثم اخلط المكونات المتبقية في وعاء صغير.",
"افرد خليط التوابل بالفرشاة على وجه قطع البيتا. ثم رتّبها في سلة القلّاية الهوائية. (لا بأس إذا تداخلت قليلًا.)",
"اطهُها بالقلّاية الهوائية على 350° فهرنهايت (175° مئوية) لمدة 3-4 دقائق للحصول على رقائق أطرى أو 5-7 دقائق للحصول على رقائق أكثر قرمشة. تفقّدها كثيرًا وأخرجها عند الوصول إلى درجة النضج المرغوبة. بالهناء والشفاء!"],
["تطهو طرازات القلّاية الهوائية بسرعات مختلفة. تفقّد الرقائق كثيرًا، بدءًا من الدقيقة الثالثة. للحصول على رقائق أطرى، اطهُها بالقلّاية الهوائية لمدة 3-4 دقائق تقريبًا.","للحصول على رقائق مقرمشة، اطهُها بالقلّاية الهوائية لمدة 5-7 دقائق تقريبًا.","لا بأس بأن تتداخل مثلثات البيتا قليلًا في سلة القلّاية. ومع ذلك، لا تجعلها تتداخل بالكامل. اعمل على دفعات عند الحاجة. ملاحظة: الدفعات اللاحقة ستنضج أسرع."],
{})
R(9957284,"كمثرى القلّاية الهوائية",
"كمثرى القلّاية الهوائية حلوة وطرية وبنكهة الكراميل ولذيذة بشكل لا يُصدَّق! حوّل الكمثرى الناضجة لديك إلى حلوى صحية ستحبها العائلة بأكملها.",
"2","حصة واحدة",
["2 حبة كمثرى بارتليت ناضجة","1.5 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة قرفة","⅛ ملعقة صغيرة جوزة الطيب","جرانولا","رقائق جوز الهند","بيكان أو جوز مفروم"],
["اغسل الكمثرى وقشّرها. (أو يمكنك ترك القشور إن فضّلت.) ثم قطّعها إلى أرباع واكشط البذور وانزع القلب. ضعها في وعاء خلط صغير.",
"أضف شراب القيقب والقرفة وجوزة الطيب فوقها وامزج برفق حتى تتغلف بالتساوي.",
"ضع الكمثرى المغلفة بالملعقة في طبقة واحدة في السلة واطهُها بالقلّاية الهوائية على 380 درجة فهرنهايت (195° مئوية) لمدة 8-12 دقيقة حتى تصبح ذهبية ومكرمَلة. لا تسكبها سكبًا!",
"أخرج الكمثرى من السلة بحذر وقدّمها مزيّنة بالجرانولا ورقائق جوز الهند والبيكان أو الجوز المفروم. بالهناء والشفاء."],
["استخدم كمثرى ناضجة للحصول على أحلى وأكثر النتائج عصارة. حاول تقطيع شرائح الكمثرى إلى قطع متساوية الحجم لتنضج بالتساوي. فإذا كانت بعض القطع أكبر، فلن تكون بالطراوة نفسها، لكنها تبقى لذيذة. لا تسكب الكمثرى في السلة سكبًا. بل ضعها في السلة بالملعقة بحذر لمنع تكسرها ورتّبها في طبقة واحدة. وإذا تبقى لديك بعض التتبيلة في قاع الوعاء، فاحتفظ بها لتغطية الكمثرى بها بعد الطهي. وفي الحالة غير المرجّحة أن يتبقى لديك شيء، فضعه في وعاء محكم الإغلاق في الثلاجة لمدة 2-3 أيام."],
{"Optional Toppings":"إضافات اختيارية"})
R(9957667,"حساء القرع العسلي في إنستانت بوت (أو على الموقد)",
"حساء القرع العسلي في إنستانت بوت كريمي ودافئ وشهي تمامًا!",
"6 حصص","حصة واحدة",
["1 بصلة صفراء مقطعة إلى مكعبات","1 جزرة كبيرة مقشرة ومقطعة إلى مكعبات","1 ساق كرفس كبيرة مقطعة إلى مكعبات","2 رطل قرع عسلي مقشر ومقطع إلى مكعبات بحجم 1 بوصة (حوالي 5 أكواب من المكعبات)","1 رطل بطاطس صفراء مقشرة ومقطعة إلى مكعبات بحجم 1 بوصة (حوالي 2 كوب من المكعبات)","1 حبة تفاح غراني سميث كبيرة مقطعة إلى قطع، منزوعة القلب والبذور","5 أكواب مرق خضار قليل الصوديوم","½ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة زنجبيل مطحون","¼ ملعقة صغيرة قرفة مطحونة","1 كوب حليب الكاجو غير المحلى أو حليب من اختيارك","ملح وفلفل حسب الرغبة","كريمة الكاجو للتزيين"],
["اختر وظيفة التقليب (السوتيه) في إنستانت بوت وأضف البصل والجزر والكرفس مع 2-3 ملاعق كبيرة من الماء. قلّبها حتى تلين، حوالي 5 دقائق.",
"أضف جميع المكونات المتبقية، باستثناء الحليب، وحرّك. أغلق الغطاء واضبط الصمام على وضع الإغلاق. الآن اضبطه على الطهي بالضغط لمدة 6 دقائق (سيستغرق حوالي 15 دقيقة للوصول إلى الضغط). وعند انتهاء المؤقت، حرّر البخار بسرعة من الصمام وافتح الغطاء عندما يكون ذلك آمنًا.",
"استخدم خلاطًا يدويًا لهرس الحساء. (أو انقله بحذر إلى خلاط عادي، مع العمل على دفعات.) حرّك فيه الحليب النباتي وأضف الملح والفلفل حسب الرغبة. ثم قدّمه مزيّنًا بكريمة الكاجو إن رغبت.",
"ضع البصل والجزر والكرفس مع 2-3 ملاعق كبيرة من الماء في قدر كبير وقلّبها حتى تلين، حوالي 5 دقائق.",
"أضف جميع المكونات المتبقية، باستثناء الحليب، وامزج جيدًا. اتركه حتى يغلي ثم اخفض الحرارة إلى نار هادئة واطبخه حتى يصبح القرع والبطاطس سهلين الاختراق بالشوكة، حوالي 20-25 دقيقة.",
"أطفئ النار، واهرس الحساء باستخدام خلاط يدوي. (أو انقله بحذر إلى خلاط عادي، مع العمل على دفعات.) حرّك فيه الحليب النباتي وأضف الملح والفلفل حسب الرغبة. ثم قدّمه مزيّنًا بكريمة الكاجو إن رغبت."],
["للحصول على عمق أكبر في النكهة (وإذا سمح الوقت)، اقطع القرع العسلي إلى نصفين واشوِه والجهة المقطوعة إلى الأسفل حتى يصبح سهل الاختراق بالشوكة. ثم أضف القرع المشوي إلى قدر الحساء واهرسهما معًا. ولتوفير الوقت، يمكنك شراء قرع عسلي مقطع جاهز من متجر البقالة. ستحتاج إلى حوالي 5 أكواب من القرع المقطع إلى مكعبات. وللحصول على وصفة خالية من المكسرات، استخدم حليب الصويا أو الشوفان أو جوز الهند (النوع الموجود في علب الكرتون وليس المعلب) بدلًا من الكاجو. يُحفظ المتبقي في الثلاجة لمدة 3-5 أيام في وعاء محكم الإغلاق أو يُجمَّد في وعاء محكم الإغلاق مناسب للمجمّد لمدة تصل إلى 3 أشهر."],
{"Instant Pot Directions":"طريقة إنستانت بوت","Stove Top Directions":"طريقة الموقد","Optional":"اختياري"})
R(9959942,"فول سوداني القلّاية الهوائية بثلاث نكهات! [دون حاجة إلى زيت]",
"ثلاث نكهات رائعة من الفول السوداني في القلّاية الهوائية طعمها كأنه محمص، لكنها أسرع بكثير في التحضير.",
"4 حصص","حصة واحدة",
["1 كوب فول سوداني نيء غير مملح","1 ملعقة كبيرة أكوافابا (ماء الحمص) أو زيت محايد النكهة","½ ملعقة صغيرة ملح البحر","⅛ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة بابريكا مدخنة","¼ ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة ملح البحر","⅛ ملعقة صغيرة فلفل أسود","1 ملعقة صغيرة سكر جوز الهند أو سكر بني","½ ملعقة صغيرة قرفة"],
["ضع الفول السوداني النيء في سلة القلّاية الهوائية في طبقة واحدة واطهُه بالقلّاية الهوائية على 350° فهرنهايت (175° مئوية) لمدة 6-8 دقائق، مع التقليب عند منتصف المدة.",
"في الأثناء، ضع ملعقة كبيرة من الأكوافابا في وعاء خلط صغير، مع خليط التوابل الذي تختاره. امزج جيدًا.",
"اسكب الفول السوداني المحمص في الوعاء مع التوابل وامزج جيدًا ليتغلف بالتساوي. ثم أعده إلى السلة واطهُه بالقلّاية الهوائية لمدة 2-4 دقائق إضافية، حتى يصبح ذهبيًا، لكن راقبه بعناية لمنعه من الاحتراق.",
"ثم اسكب الفول السوداني المطهو بالقلّاية الهوائية في وعاء واتركه يبرد لبضع دقائق قبل الاستمتاع به."],
["لا تتبّل الفول السوداني منذ بداية الطهي، وإلا قد تبدأ التوابل بالاحتراق. وإذا كنت تحضّر عدة دفعات (وهو ما يجب أن تفعله لتجرب جميع النكهات 😉)، فلاحظ أن الدفعات اللاحقة ستنضج أسرع قليلًا، لذا راقبها بعناية. المعلومات الغذائية تمثل حصة واحدة مقدارها ¼ كوب من الفول السوداني المطهو بالقلّاية الهوائية بنكهة الملح والفلفل. احفظ المتبقي في وعاء محكم الإغلاق في درجة حرارة الغرفة لمدة تصل إلى أسبوع."],
{"Salt + Pepper Roasted Peanuts":"فول سوداني محمص بالملح والفلفل","Smoky BBQ Roasted Peanuts":"فول سوداني محمص بنكهة الشواء المدخنة","Churros Roasted Peanuts":"فول سوداني محمص بنكهة التشوروس"})
R(9964071,"كوكيز الكوسا النباتي [بالشوفان]",
"كوكيز الكوسا النباتي طري ومطاطي ومليء بالخضار، ويستحق التجربة!",
"24 قطعة كوكيز","حصة واحدة",
["3 حبات موز ناضجة مهروسة (1¼ كوب مهروس)","⅓ كوب زبدة فول سوداني طبيعية ناعمة أو مقرمشة","¼ كوب شراب القيقب","2 كوب كوسا مبشورة (حوالي حبة كوسا متوسطة) (اعصرها لإزالة الرطوبة الزائدة)","1 كوب شوفان مجروش (خالٍ من الغلوتين إن فضّلت)","¼ كوب بذور القنب المقشرة (هيمب هارتس)","¼ كوب بذور الكتان أو بذور الكتان المطحونة","1 ملعقة صغيرة قرفة","1 ملعقة صغيرة بيكنغ باودر"],
["اهرس الموز في وعاء خلط كبير. ثم أضف زبدة الفول السوداني وشراب القيقب وامزج جيدًا. بعد ذلك، أضف المكونات الجافة وامزج حتى تمتزج. ستكون العجينة سميكة.",
"أضف الكوسا المبشورة إلى الوعاء نفسه وحرّك، ثم اترك العجينة جانبًا لترتاح 10 دقائق.",
"سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن صينية خبز كبيرة بورق الزبدة.",
"ثم اغرف العجينة على الصينية وشكّل الكوكيز وسوِّها، لأنها لن تنتشر كثيرًا في الفرن.",
"اخبزها لمدة 18-22 دقيقة حتى تصبح بنية ذهبية. ثم أخرجها من الفرن واتركها تبرد 5-10 دقائق لتتماسك."],
["بالنسبة للأطفال الانتقائيين في الطعام، قشّر الكوسا قبل تبشيرها لإخفاء قشرتها الخضراء الزاهية. اعصر الكوسا المبشورة فوق وعاء أو حوض المطبخ قبل إضافتها إلى العجينة. ستكون العجينة سميكة لكن الكوسا ستضيف رطوبة إلى الكوكيز. وللحصول على وصفة خالية من المكسرات، استخدم زبدة الصويا أو زبدة بذور عباد الشمس بدلًا من زبدة الفول السوداني. يُحفظ الكوكيز المتبقي في درجة حرارة الغرفة لمدة يومين، أو في الثلاجة لمدة تصل إلى 6 أيام. جمّده في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر بعد تبريده إلى درجة حرارة الغرفة أولًا."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة"})
R(9964694,"كريما فريسكا نباتية أو كريم فريش نباتي",
"كل ما تحتاجه هو 4 مكونات و5 دقائق للحصول على كريما فريسكا (أو كريم فريش) نباتية كريمية ولذيذة لتسكبها على كل شيء!",
"8 حصص","حصة واحدة",
["1 كوب كاجو نيء","½-¾ كوب ماء عذب (أحب نصف كوب إضافة إلى ملعقتين كبيرتين)","¼ كوب عصير ليمون أخضر (حوالي حبة ليمون أخضر كبيرة أو حبتين صغيرتين)","½ ملعقة صغيرة ملح البحر"],
["ضع جميع المكونات في خلاط عالي السرعة، مثل فيتامكس، وشغّله حتى يصبح الخليط ناعمًا وكريميًا. ابدأ بنصف كوب من الماء وأضف المزيد 1-2 ملعقة كبيرة في كل مرة حتى تصل إلى القوام المرغوب. (أجد أن نصف كوب إضافة إلى ملعقتين كبيرتين هو المثالي.)",
"قدّمها مع الذرة على الكوز أو الناتشوز أو التاكو أو الحساء أو الفلفل الحار (تشيلي) أو فوق السلطة."],
["إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو في ماء مغلي لمدة 30 دقيقة، ثم صفِّه قبل الخلط. فوقت النقع سيجعله طريًا، مما يسهّل تفتيته. ضع الكريما في الثلاجة قبل استخدامها لأن طعمها أفضل وهي باردة. وإذا لم يسمح الوقت، فإن طعمها يبقى رائعًا وهي طازجة. وللحصول على وصفة خالية من المكسرات، يمكنك استبدال الكاجو ببذور عباد الشمس النيئة أو بذور القرع (بيبيتاس) للحصول على نتائج مماثلة. تأكد من استخدام النوع غير المملح أو احذف الملح. يُحفظ المتبقي في الثلاجة لمدة تصل إلى 5 أيام، أو يُجمَّد لمدة تصل إلى 3 أشهر."],
{})
R(9966381,"سلطة الفاصولياء النباتية",
"سلطة فاصولياء نباتية مشبعة وشهية يسيل لها اللعاب!",
"6 حصص","حصة واحدة",
["علبة حمص 15 أونصة مصفاة ومغسولة (حوالي 1.5 كوب)","علبة فاصولياء سوداء 15 أونصة مصفاة ومغسولة (حوالي 1.5 كوب)","علبة فاصولياء حمراء (كلى حمراء) 15 أونصة مصفاة ومغسولة (حوالي 1.5 كوب)","1.5 كوب خيار مقطع إلى مكعبات (حوالي نصف حبة خيار طويلة)","¼ كوب بصل أحمر مقطع إلى مكعبات","1 حبة أفوكادو مقطعة إلى مكعبات","½ كوب أوراق ريحان مفرومة ناعمًا","¼ كوب عصير ليمون (حوالي ليمونة متوسطة واحدة)","2 ملعقة كبيرة خل بلسمي","1 ملعقة كبيرة شراب القيقب","ملح وفلفل حسب الرغبة"],
["صفِّ الفاصولياء واغسلها، وقطّع جميع الخضار وضعها في وعاء كبير.",
"في وعاء صغير آخر، اخلط مكونات صلصة السلطة. ثم اسكب الصلصة على السلطة وامزج جيدًا لتتغلف بالتساوي. استمتع بها فورًا أو ضعها في الثلاجة لمدة ساعة قبل التقديم."],
["خطّط لتحضير الطبق قبل التقديم بحوالي ساعة لأن طعمه أفضل وهو بارد.","يكون طعم هذه السلطة أفضل في اليوم نفسه الذي تُحضَّر فيه، لكن المتبقي يُحفظ في الثلاجة لمدة 2-3 أيام،"],
{"For the Salad":"للسلطة","For the Dressing":"للصلصة"})
R(9966537,"سموذي الموز والجوز الصحي",
"سموذي الموز والجوز الغني بالبروتين هذا هو الطريقة المثالية لبدء صباحك، أو لمنحك دفعة الطاقة التي تحتاجها بعد الظهر!",
"حصتان","حصة واحدة",
["2 كوب حليب اللوز غير المحلى أو حليب من اختيارك","⅓ كوب جوز","2 موزة مجمدة","¼ ملعقة صغيرة قرفة"],
["ضع جميع المكونات في الخلاط وشغّله حتى يصبح ناعمًا. بالهناء والشفاء!"],
["لا تستبدل الموز المجمد بالطازج إلا عند الضرورة القصوى. فالموز المجمد هو الأفضل فعلًا. وإذا لم يكن لديك موز مجمد، فيمكنك تقشير الموز الطازج وتقطيعه وتجميده لمدة 30-60 دقيقة. احرص على تقطيعه أولًا ليتجمد أسرع. ولاستخدام الموز الطازج، إذا لم يكن لديك الوقت لتجميده فعلًا، فأضف حفنة من مكعبات الثلج إلى السموذي أيضًا للحصول على نتائج مماثلة. تأكد من أن الموز شديد النضج. فالحلاوة هنا كلها تأتي من الموز، لذا كلما كان أنضج كان أفضل. اختر موزًا عليه بقع بنية على القشرة قبل التجميد. وللحصول على سموذي أحلى، يمكنك إضافة ملعقة صغيرة من شراب القيقب الطبيعي أو 2-3 حبات تمر منزوعة النوى. وإذا لم يكن لديك جوز، فيمكنك استبداله باللوز أو البندق أو البيكان. وللحصول على أفضل النتائج، استخدم خلاطًا عالي السرعة، وإذا لم يكن لديك واحد، فانقع الجوز لحوالي 10-15 دقيقة في ماء عذب ثم صفِّه. فهذا سيسهّل على الخلاط معالجته دون ترك أي خشونة. تُنتج الوصفة حوالي 3.5 كوب."],
{})
R(9967440,"صلصة الإنشيلادا المنزلية",
"صلصة الإنشيلادا المنزلية جاهزة في 15 دقيقة، فيمكنك أن تودّع المعلبة إلى الأبد! إنها حارة ولذيذة وسهلة!",
"2 كوب","4 ملاعق كبيرة",
["1-3 حبات هالبينو مفرومة ناعمًا جدًا","2 كوب مرق خضار قليل الصوديوم","4 ملاعق كبيرة معجون طماطم","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","1 ملعقة صغيرة كمون","½ ملعقة صغيرة ملح البحر","1 ملعقة كبيرة نشا الذرة للتثخين، اختياري"],
["ضع الهالبينو مع ملعقة كبيرة أو ملعقتين من المرق في قدر صغير وقلّبه لمدة دقيقتين.",
"أضف جميع المكونات المتبقية، وامزج جيدًا واتركها حتى تغلي. ثم اخفض الحرارة إلى متوسطة-منخفضة واتركها على نار هادئة لمدة 8 دقائق حتى يتقلص حجمها قليلًا.",
"استخدمها في أطباقك المكسيكية المفضلة."],
["استخدم من 1 إلى 3 حبات هالبينو حسب درجة الحرارة التي تفضلها. فإذا أردت صلصة أخف، فاكتفِ بحبة هالبينو واحدة وأزل البذور. وللدرجة المتوسطة، استخدم 1-2 مع الإبقاء على البذور. وللصلصة الحارة، استخدم 3 حبات هالبينو مع بذورها. احفظ المتبقي في وعاء أو برطمان محكم الإغلاق في الثلاجة لمدة تصل إلى 5 أيام. أو يمكنك تجميده لمدة تصل إلى شهر. ويمكنك خلط الصلصة بعد غليها على نار هادئة إن فضّلت. لكن إذا فرمت الهالبينو ناعمًا جدًا، فلا حاجة لذلك. ونشا الذرة الاختياري يعمل جيدًا إذا كنت ستستخدم الصلصة فورًا كما هي. أما إذا كنت ستضيف الصلصة إلى طاجن الإنشيلادا بالخضار الخاص بي، فتجاوز نشا الذرة. المعلومات الغذائية لـ ⅛ من الصلصة، أي حوالي 4 ملاعق كبيرة أو ¼ كوب."],
{})
R(9968027,"ناتشوز الجاك فروت المسحوب مع صلصة الشواء المنزلية",
"ناتشوز نباتية لذيذة مغطاة بالجاك فروت المغمور بصلصة الشواء المنزلية اللذيذة. جاهزة في 20 دقيقة!",
"4 حصص","حصة واحدة",
["220 غرام كيس رقائق تورتيلا متعددة الحبوب أو ما تختاره","علبة جاك فروت أخضر صغير (غير ناضج) وزنها 20 أونصة مصفاة ومغسولة (النوع المعلب في الماء أو المحلول الملحي، وليس الشراب)","3 ملاعق كبيرة معجون طماطم","¼ كوب خل التفاح","1 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة خردل أصفر","2 ملعقة كبيرة تاماري أو صلصة صويا (أو ½ ملعقة صغيرة ملح)","¼ كوب ماء","2 ملعقة صغيرة مسحوق البصل","2 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة بابريكا مدخنة","¼ ملعقة صغيرة فلفل كايين (اختياري)","فاصولياء سوداء","ذرة","هالبينو","زيتون","كزبرة خضراء طازجة","جواكامولي","كريمة الكاجو","صلصة سالسا","صلصة جبن خالية من المكسرات","غموس «هالبينو بوبر» الحار"],
["اخلط جميع مكونات صلصة الشواء في وعاء متوسط وامزج جيدًا. اتركها جانبًا.",
"فتّت قطع الجاك فروت بيديك أو بشوكتين. وسيتفتت بسهولة تامة، ثم ضعه في مقلاة كبيرة. ثم اسكب الصلصة فوقه وامزج جيدًا.",
"على نار متوسطة، اطبخ الجاك فروت في الصلصة، وسيكون مائيًا قليلًا في البداية لكنه سيمتص الصلصة بسرعة أثناء الطهي. وسيستغرق ذلك حوالي 5-8 دقائق.",
"في الأثناء، رتّب الرقائق في طبق تقديم، وعندما يصبح جاهزًا، ضع فوقه الجاك فروت والإضافات التي تختارها. قدّم ناتشوز الجاك فروت مع الجواكامولي وكريمة الكاجو و/أو السالسا."],
["احرص على شراء جاك فروت معلب في الماء أو المحلول الملحي، وليس في الشراب. فالنوع المعلب في الشراب شديد الحلاوة وأنت تريده أن يمتص نكهة صلصة الشواء، وألا يطغى عليه طعم الشراب. وإذا كان وقتك ضيقًا، أو لا تريد تحضير صلصة الشواء بنفسك، فيمكنك استبدالها بصلصة جاهزة. استخدم حوالي ¾ كوب من الصلصة الجاهزة بدلًا من النسخة المنزلية. وإذا كنت تفضّل بعض الحواف المقرمشة في الجاك فروت، فانقله بعد الطهي إلى صينية خبز في طبقة واحدة واخبزه على 375 درجة (190° مئوية) لمدة 15-20 دقيقة قبل إضافته إلى الناتشوز. وللحصول على رقائق خالية من الزيت، إليك وصفة من Sweet Simple Vegan لتحضير رقائق التورتيلا الصحية بنفسك. تذكّر أن الجاك فروت هو نجم الطبق، لذا ضع طبقة سخية منه على الرقائق قبل رش الإضافات الأخرى. وإذا بقي لديك شيء، فاحفظه في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 5 أيام. استخدم المتبقي لعمل ساندويتش نباتي على نمط «لحم الخنزير المسحوب» مغطى بسلطة الكولسلو النباتية الكريمية الخاصة بي."],
{"For the Jackfruit":"للجاك فروت","Optional Toppings & Dips":"إضافات وغموس اختيارية"})
